from __future__ import annotations

from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Mapping, MutableMapping, Optional, Sequence, Union
import json


JsonScalar = Union[str, int, float, bool, None]
JsonValue = Union[JsonScalar, Dict[str, Any], List[Any]]


def _normalize_json_value(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {str(k): _normalize_json_value(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_normalize_json_value(v) for v in value]
    if isinstance(value, tuple):
        return [_normalize_json_value(v) for v in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception:
            pass
    return str(value)


def normalize_document(document: Mapping[str, Any]) -> Dict[str, Any]:
    return {str(k): _normalize_json_value(v) for k, v in document.items()}


def normalize_documents(documents: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    return [normalize_document(document) for document in documents]


def _coerce_metadata(metadata: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    return normalize_document(metadata or {})


@dataclass
class DatabaseRequest:
    container: Optional[str] = None
    collection: Optional[str] = None
    partition_key: Optional[str] = None
    document_id: Optional[str] = None
    consistency: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        data = asdict(self)
        data["metadata"] = _coerce_metadata(self.metadata)
        return {k: v for k, v in data.items() if v is not None}


@dataclass
class UpsertDocumentRequest(DatabaseRequest):
    document: Dict[str, Any] = field(default_factory=dict)
    if_match_etag: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["document"] = normalize_document(self.document)
        if self.if_match_etag is not None:
            data["if_match_etag"] = self.if_match_etag
        return data


@dataclass
class FetchDocumentRequest(DatabaseRequest):
    def to_dict(self) -> Dict[str, Any]:
        return super().to_dict()


@dataclass
class QueryDocumentsRequest(DatabaseRequest):
    field_name: Optional[str] = None
    field_value: Any = None
    query: Optional[str] = None
    limit: Optional[int] = None
    continuation_token: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        if self.field_name is not None:
            data["field_name"] = self.field_name
        if self.field_value is not None:
            data["field_value"] = _normalize_json_value(self.field_value)
        if self.query is not None:
            data["query"] = self.query
        if self.limit is not None:
            data["limit"] = self.limit
        if self.continuation_token is not None:
            data["continuation_token"] = self.continuation_token
        return data


@dataclass
class ConditionalUpdateRequest(DatabaseRequest):
    updates: Dict[str, Any] = field(default_factory=dict)
    conditions: Dict[str, Any] = field(default_factory=dict)
    if_match_etag: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["updates"] = normalize_document(self.updates)
        data["conditions"] = normalize_document(self.conditions)
        if self.if_match_etag is not None:
            data["if_match_etag"] = self.if_match_etag
        return data


@dataclass
class RecordSummaryRequest(DatabaseRequest):
    documents: Sequence[Mapping[str, Any]] = field(default_factory=list)
    max_items: Optional[int] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["documents"] = normalize_documents(self.documents)
        if self.max_items is not None:
            data["max_items"] = self.max_items
        return data


@dataclass
class RecordTextSafetyRequest(DatabaseRequest):
    text_fields: Sequence[str] = field(default_factory=list)
    document: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["text_fields"] = list(self.text_fields)
        data["document"] = normalize_document(self.document)
        return data


@dataclass
class RecordTranslateRequest(DatabaseRequest):
    text_fields: Sequence[str] = field(default_factory=list)
    document: Dict[str, Any] = field(default_factory=dict)
    target_language: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["text_fields"] = list(self.text_fields)
        data["document"] = normalize_document(self.document)
        if self.target_language is not None:
            data["target_language"] = self.target_language
        return data


@dataclass
class RecordExportArchiveRequest(DatabaseRequest):
    export_uri: Optional[str] = None
    snapshot: Dict[str, Any] = field(default_factory=dict)
    attachment_name: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        if self.export_uri is not None:
            data["export_uri"] = self.export_uri
        data["snapshot"] = normalize_document(self.snapshot)
        if self.attachment_name is not None:
            data["attachment_name"] = self.attachment_name
        return data


@dataclass
class DatabaseResponse:
    ok: bool = True
    status_code: Optional[int] = None
    request_id: Optional[str] = None
    message: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        data = asdict(self)
        data["metadata"] = _coerce_metadata(self.metadata)
        return {k: v for k, v in data.items() if v is not None}


@dataclass
class DocumentResponse(DatabaseResponse):
    document: Dict[str, Any] = field(default_factory=dict)
    etag: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["document"] = normalize_document(self.document)
        if self.etag is not None:
            data["etag"] = self.etag
        return data


@dataclass
class QueryDocumentsResponse(DatabaseResponse):
    documents: List[Dict[str, Any]] = field(default_factory=list)
    continuation_token: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["documents"] = normalize_documents(self.documents)
        if self.continuation_token is not None:
            data["continuation_token"] = self.continuation_token
        return data


@dataclass
class SummaryResponse(DatabaseResponse):
    summary: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["summary"] = normalize_document(self.summary)
        return data


@dataclass
class SafetyResponse(DatabaseResponse):
    unsafe: bool = False
    reasons: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["unsafe"] = self.unsafe
        data["reasons"] = list(self.reasons)
        return data


@dataclass
class TranslationResponse(DatabaseResponse):
    translated_document: Dict[str, Any] = field(default_factory=dict)
    target_language: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        data["translated_document"] = normalize_document(self.translated_document)
        if self.target_language is not None:
            data["target_language"] = self.target_language
        return data


@dataclass
class ArchiveResponse(DatabaseResponse):
    archive_uri: Optional[str] = None
    archive_id: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        data = super().to_dict()
        if self.archive_uri is not None:
            data["archive_uri"] = self.archive_uri
        if self.archive_id is not None:
            data["archive_id"] = self.archive_id
        return data


def from_json(payload: str) -> Dict[str, Any]:
    value = json.loads(payload)
    if isinstance(value, Mapping):
        return normalize_document(value)
    raise ValueError("JSON payload must decode to an object")


def to_json(document: Mapping[str, Any]) -> str:
    return json.dumps(normalize_document(document), ensure_ascii=False, separators=(",", ":"))

